using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using Microsoft.Win32;using Forms=System.Windows.Forms;
public sealed class TerminalInspector:Border,IDisposable{
 Server server;string directory;int version;CancellationTokenSource cancel=new CancellationTokenSource();bool locationReady,locationLoading,disposed;string pendingPath;readonly ListBox entries;readonly Button uploadAction,openAction;readonly TextBlock count,pathLabel,diskValue,diskDetail;readonly PixelMeter diskMeter;readonly WrapPanel crumbs;List<FileEntry> data=new List<FileEntry>();public Action CloseRequested;public Action<Server,string,string[]> FilesRequested;public string CurrentPath{get{return directory;}}
 public TerminalInspector(){HorizontalAlignment=HorizontalAlignment.Stretch;Background=Theme.Surface;BorderBrush=Theme.Line;BorderThickness=new Thickness(1,0,0,0);Padding=new Thickness(18,12,18,14);var dock=new DockPanel();var heading=new Grid{Height=36,Margin=new Thickness(0,0,0,14)};heading.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});heading.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var title=new StackPanel{Orientation=Orientation.Horizontal};title.Children.Add(new IconView("FolderTree",19));var text=Theme.Text("文件",17,Theme.Ink,false,true);text.Margin=new Thickness(8,0,0,0);title.Children.Add(text);heading.Children.Add(title);var close=Theme.IconAction("X","",()=>{if(CloseRequested!=null)CloseRequested();});close.Width=28;close.Padding=new Thickness(4);Grid.SetColumn(close,1);heading.Children.Add(close);DockPanel.SetDock(heading,Dock.Top);dock.Children.Add(heading);
 crumbs=new WrapPanel{Margin=new Thickness(0,0,0,10)};DockPanel.SetDock(crumbs,Dock.Top);dock.Children.Add(crumbs);pathLabel=Theme.Text("",12,Theme.Muted);pathLabel.Visibility=Visibility.Collapsed;
 var tools=new Grid{Height=38,Margin=new Thickness(0,0,0,8)};tools.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});tools.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});tools.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});count=Theme.Text("正在读取",12,Theme.Muted);tools.Children.Add(count);var upload=uploadAction=Theme.IconAction("Upload","",PickUpload);upload.ToolTip="上传文件或文件夹";upload.Width=30;upload.Padding=new Thickness(5);Grid.SetColumn(upload,1);tools.Children.Add(upload);var refresh=Theme.IconAction("RefreshCw","",()=>Navigate(directory,true));refresh.ToolTip="刷新目录";refresh.Width=30;refresh.Padding=new Thickness(5);Grid.SetColumn(refresh,2);tools.Children.Add(refresh);DockPanel.SetDock(tools,Dock.Top);dock.Children.Add(tools);
 var bottom=new StackPanel{Margin=new Thickness(0,12,0,0)};bottom.Children.Add(new Border{Height=1,Background=Theme.Line,Margin=new Thickness(0,0,0,14)});var usage=new Grid();usage.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});usage.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});usage.Children.Add(Theme.Text("根目录存储",12,Theme.Muted));diskValue=Theme.Text("—",12,Theme.Ink);Grid.SetColumn(diskValue,1);usage.Children.Add(diskValue);bottom.Children.Add(usage);diskMeter=new PixelMeter(0,Theme.B("#9CA9D0"),4){Blocks=45,Margin=new Thickness(0,12,0,10)};bottom.Children.Add(diskMeter);diskDetail=Theme.Text("",11,Theme.Muted);diskDetail.TextWrapping=TextWrapping.Wrap;bottom.Children.Add(diskDetail);var open=openAction=Theme.Action("在文件页打开 ↗",()=>{if(locationReady&&FilesRequested!=null&&server!=null)FilesRequested(server,directory,null);});open.FontSize=12;open.HorizontalAlignment=HorizontalAlignment.Left;open.Padding=new Thickness(0);open.Margin=new Thickness(0,10,0,0);bottom.Children.Add(open);DockPanel.SetDock(bottom,Dock.Bottom);dock.Children.Add(bottom);
 entries=new ListBox{Background=Brushes.Transparent,BorderThickness=new Thickness(0),HorizontalContentAlignment=HorizontalAlignment.Stretch,Padding=new Thickness(0),AllowDrop=true};entries.MouseDoubleClick+=(s,e)=>{var row=entries.SelectedItem as ListBoxItem;var item=row==null?null:row.Tag as FileEntry;if(item!=null&&item.IsDirectory)Navigate(item.FullPath,false);};entries.PreviewDragOver+=(s,e)=>{e.Effects=locationReady&&e.Data.GetDataPresent(DataFormats.FileDrop)?DragDropEffects.Copy:DragDropEffects.None;e.Handled=true;};entries.Drop+=(s,e)=>{if(!locationReady||server==null||directory==null||!e.Data.GetDataPresent(DataFormats.FileDrop))return;if(FilesRequested!=null)FilesRequested(server,directory,(string[])e.Data.GetData(DataFormats.FileDrop));e.Handled=true;};dock.Children.Add(entries);Child=dock;}
 public void SetLocation(Server device,string path){if(device==null)return;bool changed=server==null||FileTools.Key(device)!=FileTools.Key(server);server=device.Copy();if(!changed&&locationLoading&&(path??"")==pendingPath)return;if(changed||string.IsNullOrEmpty(directory)||(!string.IsNullOrEmpty(path)&&path!=directory))Navigate(path,false);}
 async void Navigate(string path,bool force){if(server==null)return;int stamp=++version;cancel.Cancel();cancel.Dispose();cancel=new CancellationTokenSource();var token=cancel.Token;var device=server.Copy();locationLoading=true;pendingPath=path??"";locationReady=false;uploadAction.IsEnabled=false;openAction.IsEnabled=false;entries.Items.Clear();crumbs.Children.Clear();directory=null;data.Clear();count.Text="正在读取…";try{var result=await Task.Run(async()=>{using(var connection=new FileConnection(device)){await connection.Connect(token).ConfigureAwait(false);string selected=string.IsNullOrEmpty(path)?connection.Home:path;return Tuple.Create(selected,connection.List(selected,token));}},token);if(token.IsCancellationRequested||stamp!=version||disposed||Dispatcher.HasShutdownStarted)return;await Dispatcher.InvokeAsync((Action)(()=>{if(token.IsCancellationRequested||stamp!=version||disposed)return;directory=result.Item1;data=result.Item2;locationReady=true;uploadAction.IsEnabled=true;openAction.IsEnabled=true;pathLabel.Text=directory;Render();}));}catch(OperationCanceledException){}catch(Exception ex){if(stamp!=version||disposed||Dispatcher.HasShutdownStarted)return;ReportReadFailure(stamp,ex.Message);}finally{if(stamp==version)locationLoading=false;}}
 void ReportReadFailure(int stamp,string message){Dispatcher.BeginInvoke((Action)(()=>{if(stamp!=version||disposed)return;count.Text="读取失败";count.ToolTip=message;}));}
 void Render(){entries.Items.Clear();foreach(var item in data){var row=new Grid{Height=38};row.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});row.Children.Add(new IconView(item.IsDirectory?"Folder":"FileText",17,item.IsDirectory?Theme.Teal:Theme.Muted));var title=Theme.Text(item.Name,14,Theme.Ink);title.Margin=new Thickness(9,0,0,0);Grid.SetColumn(title,1);row.Children.Add(title);entries.Items.Add(new ListBoxItem{Content=row,Tag=item,Padding=new Thickness(4,0,4,0),ToolTip=item.FullPath});}count.Text=data.Count+" 个项目";crumbs.Children.Clear();if(string.IsNullOrEmpty(directory))return;var parts=FileTools.PathParts(server.IsLocal,directory);if(parts.Count>2){var more=Theme.Action("…",()=>{});more.Width=30;more.Padding=new Thickness(0);more.Click+=(s,e)=>{var menu=new ContextMenu{Resources=Theme.Resources()};foreach(var part in parts.Take(parts.Count-2)){var p=part;var item=new MenuItem{Header=p.Item1};item.Click+=(a,b)=>Navigate(p.Item2,false);menu.Items.Add(item);}more.ContextMenu=menu;menu.IsOpen=true;};crumbs.Children.Add(more);}foreach(var part in parts.Skip(Math.Max(0,parts.Count-2))){var p=part;var button=Theme.Action(p.Item1,()=>Navigate(p.Item2,false));button.FontSize=13;button.Padding=new Thickness(5,0,5,0);button.MaxWidth=120;button.ToolTip=p.Item2;crumbs.Children.Add(button);crumbs.Children.Add(new IconView("ChevronRight",12));}}
 void PickUpload(){if(server==null||!locationReady)return;var menu=new ContextMenu{Resources=Theme.Resources()};var file=new MenuItem{Header="上传文件…"};file.Click+=(s,e)=>{var dialog=new OpenFileDialog{Multiselect=true};if(dialog.ShowDialog()==true&&FilesRequested!=null)FilesRequested(server,directory,dialog.FileNames);};var folder=new MenuItem{Header="上传文件夹…"};folder.Click+=(s,e)=>{using(var dialog=new Forms.FolderBrowserDialog()){if(dialog.ShowDialog()==Forms.DialogResult.OK&&FilesRequested!=null)FilesRequested(server,directory,new[]{dialog.SelectedPath});}};menu.Items.Add(file);menu.Items.Add(folder);menu.IsOpen=true;}
 public void UpdateMetrics(Metrics value){if(value==null){diskValue.Text="—";diskMeter.Value=0;diskDetail.Text="";return;}var match=System.Text.RegularExpressions.Regex.Match(value.Disk??"",@"([0-9.]+)%");double percent=match.Success?GpuCard.Number(match.Groups[1].Value):0;diskValue.Text=match.Success?percent.ToString("0")+"%":"—";diskMeter.Value=percent;diskDetail.Text=value.Disk;}
